  '{"slug":"street-flood-depth","version":1,"name":"Street flood depth","why_it_matters":"Urban flood models are calibrated against very few street-level measurements. Depth readings with exact place and time show which streets flood, how deep, and how fast water recedes.","safety":{"level":"elevated","check_in_question":"Are you on a sidewalk, curb, or other dry ground, away from moving water?","rules":["Never enter or drive through floodwater.","Stay on dry ground at least 2 meters from moving water.","Captures pause automatically inside life-threatening weather warnings.","If you feel unsafe, stop. There is no penalty for ending a session."]},"capture":{"mode":"burst","frames":3,"frame_interval_ms":600,"orientation":"landscape","max_tilt_deg":15,"required_elements":[{"id":"water_surface","label":"Water surface","description":"Standing or moving water on a street, sidewalk, or lot."},{"id":"reference_object","label":"Reference object","description":"An object of known height partly submerged: curb, car tire, fire hydrant, sign post, or measuring stick."},{"id":"waterline","label":"Waterline visible","description":"The line where water meets the reference object is clearly visible."}],"framing_tips":["Hold the phone level.","Put the reference object in the middle of the frame.","Stand 2 to 6 meters away."],"challenges":[{"id":"step_left","instruction":"Take one slow step to your left while I capture.","expect":"Viewpoint shifts left across the burst with consistent parallax."},{"id":"step_closer","instruction":"Take one small step closer while I capture.","expect":"Reference object grows in frame across the burst."},{"id":"tilt_down","instruction":"Slowly tilt the phone down toward the waterline while I capture.","expect":"Framing moves downward across the burst."}],"field_questions":[{"id":"water_state","question":"Is the water moving or still?","type":"enum","options":["still","slow","fast"]},{"id":"debris_present","question":"Do you see debris or trash in the water?","type":"boolean"}]},"extraction_schema":{"type":"object","properties":{"depth_cm":{"type":["number","null"],"description":"Estimated water depth at the reference object, in centimeters."},"depth_confidence":{"type":"number","minimum":0,"maximum":1},"reference_object_type":{"type":"string","enum":["curb","tire","hydrant","sign_post","measuring_stick","other"]},"reference_object_assumed_height_cm":{"type":["number","null"]},"surface_type":{"type":"string","enum":["road","sidewalk","parking_lot","yard","other"]},"water_state":{"type":"string","enum":["still","slow","fast","unknown"]},"debris_present":{"type":["boolean","null"]},"notes":{"type":"string"}},"required":["depth_cm","depth_confidence","reference_object_type","surface_type","water_state"]},"acceptance":{"min_protocol_score":0.7,"min_authenticity_score":0.8,"precipitation_plausibility":{"lookback_hours":48,"min_total_mm":5},"corroboration_radius_m":300,"corroboration_window_min":60,"corroboration_field":"depth_cm","corroboration_tolerance":10},"pricing":{"urgency_tau_hours":3},"example_image_prompt":"Photorealistic landscape street-level photo of shallow floodwater on an urban street reaching halfway up a standard concrete curb and the lower part of a parked car''s tire, overcast daylight, camera held level about 3 meters away, waterline clearly visible on the curb and tire. Instructional reference photo."}'::jsonb, 'published', '00000000-0000-4000-8000-000000000001'
